// ── Anansi outreach batch composer ─────────────────────────────────────────
// Contract: the canonical CSV from the vault (Schema (n8n) tab in
// anansi-atlas-sales-pipeline-MASTER.xlsx). Upsert-on-email / warm-wins /
// never-downgrade reconciliation is ported below (JS twin of
// 08_Assets/reconcile_pipeline.py) — feed incoming CSVs through reconcileRows()
// if you wire an ingest branch; the daily draft flow only READS the canon.
//
// Env expected on the n8n container:
//   OUTREACH_DIR            – mounted vault 08_Assets folder
//   WALKTHROUGH_VIDEO_URL   – unlisted YouTube walkthrough (the hero CTA)
//   STRIPE_MONTHLY_URL, STRIPE_ANNUAL_URL, CAL_URL – offer links
//   BATCH_SIZE              – default 15

const CANON = ['lead_id','dedup_key','is_warm','list_segment','warmth','campaign_track','ref','organization','contact_name','first_name','last_name','role_title','email','relationship_depth','focus_angle','subject_line','stage','next_action','why_fit','website','email_status','source','date_added','last_updated','notes'];

function parseCsv(text) {
  const rows = [];
  let cur = [''], inQ = false, row = cur;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQ) {
      if (ch === '"') { if (text[i+1] === '"') { row[row.length-1] += '"'; i++; } else inQ = false; }
      else row[row.length-1] += ch;
    } else if (ch === '"') inQ = true;
    else if (ch === ',') row.push('');
    else if (ch === '\n' || ch === '\r') { if (row.length > 1 || row[0] !== '') { rows.push(row); } row = ['']; if (ch === '\r' && text[i+1] === '\n') i++; rows.length && (cur = row); }
    else row[row.length-1] += ch;
  }
  if (row.length > 1 || row[0] !== '') rows.push(row);
  const head = rows.shift().map(h => h.trim().toLowerCase());
  return rows.map(r => Object.fromEntries(head.map((h, i) => [h, (r[i] || '').trim()])));
}

// JS twin of reconcile_pipeline.py — upsert on email, warm wins, never downgrade.
function reconcileRows(baseRows, incomingRows) {
  const nemail = e => (e || '').trim().toLowerCase();
  const today = new Date().toISOString().slice(0, 10);
  const by = new Map(baseRows.map(r => [r.dedup_key, r]));
  for (const raw of incomingRows) {
    const low = Object.fromEntries(Object.entries(raw).map(([k, v]) => [k.toLowerCase().trim(), v]));
    const key = nemail(low.email);
    if (!key) continue;
    if (by.has(key)) {
      const r = by.get(key);
      for (const c of CANON) if (low[c]) r[c] = low[c];
      if ((low.is_warm || '').toUpperCase() === 'TRUE' || r.is_warm === 'TRUE') r.is_warm = 'TRUE';
      r.last_updated = today;
    } else {
      const r = Object.fromEntries(CANON.map(c => [c, low[c] || '']));
      r.email = low.email; r.dedup_key = key;
      r.lead_id = 'AA-' + key.split('').reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) >>> 0, 0).toString(16).toUpperCase().padStart(10, '0').slice(0, 10);
      if (!r.is_warm) r.is_warm = 'FALSE';
      if (!r.list_segment) r.list_segment = r.is_warm === 'TRUE' ? 'warm' : 'cold_florida_crm';
      if (!r.email_status) r.email_status = 'not_sent';
      r.date_added = today; r.last_updated = today;
      baseRows.push(r); by.set(key, r);
    }
  }
  return baseRows;
}

const csvText = Buffer.from($input.first().binary.data.data, 'base64').toString('utf8');
const leads = parseCsv(csvText);

const BATCH = parseInt($env.BATCH_SIZE || '15', 10);
const warmthRank = { hot: 0, warm: 1, reconnect: 2, cold: 3 };
const queue = leads
  .filter(l => l.email && l.email_status === 'not_sent')
  .sort((a, b) => (a.is_warm === b.is_warm ? 0 : a.is_warm === 'TRUE' ? -1 : 1)
    || ((warmthRank[a.warmth] ?? 9) - (warmthRank[b.warmth] ?? 9)));
const batch = queue.slice(0, BATCH);

const video = $env.WALKTHROUGH_VIDEO_URL || '⟦VIDEO LINK — set WALKTHROUGH_VIDEO_URL⟧';
const monthly = $env.STRIPE_MONTHLY_URL || 'https://buy.stripe.com/3cI28q4PM4Xw3cPfnzbV601';
const annual = $env.STRIPE_ANNUAL_URL || '';
const cal = $env.CAL_URL || 'https://cal.com/marcus-scott-br7maf/founder-walkthrough';

function draftFor(l) {
  const first = l.first_name || (l.contact_name || '').split(' ')[0] || 'there';
  const warm = l.is_warm === 'TRUE';
  const opening = warm
    ? `Hi ${first},\n\nIt's Marcus — ${l.relationship_depth || l.why_fit || 'we crossed paths in my Aeras days'}.`
    : `Hi ${first},\n\nI'm Marcus Scott, founder of Anansi Atlas here in Central Florida. I'm reaching out because ${l.why_fit || `${l.organization} sits right in the middle of the work we map`}.`;
  const angle = l.focus_angle ? `\n\n${l.focus_angle}` : '';
  const body = `${opening}${angle}\n\nI've built Anansi Atlas: it maps the web of opportunity around a nonprofit's mission — aligned funders, partners, government pathways, free capacity-building resources — into one clear brief with a readiness read and a 30-day action plan.\n\n▶ Here's a 3-minute look at the actual platform (no pitch deck, the real thing):\n${video}\n\nIf it clicks, two doors — no pressure either way:\n• Claim a founding seat ($150/mo${annual ? `, or ${'$'}1,440/yr — save 20%` : ''}, locked for life): ${monthly}${annual ? `\n  Annual: ${annual}` : ''}\n• Or grab 45 minutes with me first: ${cal}\n\nEither way — glad ${l.organization} is out there doing this work.\n\n— Marcus\nAnansi Atlas · The Web of Opportunity · anansiatlas.com`;
  return {
    lead_id: l.lead_id, organization: l.organization, contact: l.contact_name,
    email: l.email, warmth: l.warmth || (warm ? 'warm' : 'cold'), segment: l.list_segment,
    subject: l.subject_line || `Thought of ${l.organization} while building this`,
    body,
  };
}

const drafts = batch.map(draftFor);
const digest = drafts.map((d, i) =>
  `━━━ ${i + 1}/${drafts.length} · ${d.organization} · ${d.warmth.toUpperCase()} ━━━\nTo: ${d.contact} <${d.email}>\nSubject: ${d.subject}\n\n${d.body}\n`
).join('\n\n');

return [{ json: {
  date: new Date().toISOString().slice(0, 10),
  batch_size: drafts.length,
  remaining_after: Math.max(0, queue.length - drafts.length),
  digest,
  drafts,
} }];
